#!/usr/bin/env python3
"""
Round 130b (culprits-tiles-more), 2 October 2026. Upload after round129b_tiles.py.

- scripts/open_payments.py (new): CMS Open Payments general payments to
  prescribers, added up by state and company by CMS's own data service.

Every file is written whole, and only if it differs.
"""
import base64, pathlib

FILES = {
    'scripts/open_payments.py': '',
}


def main():
    for name, data in FILES.items():
        p = pathlib.Path(name)
        new = base64.b64decode(data)
        if p.exists() and p.read_bytes() == new:
            print(f"  {name}: already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(new)
        print(f"  {name}: written")


if __name__ == "__main__":
    main()
